/* ============================================================================
   CHANGES: a plain-words name for what one edit did, for "Undo: delete page “The Cellar”" and the History list.
   Pure functions over two saved copies of the story (JSON text): nothing here touches the screen or the story.
   Copyright (c) 2026 LFC Foundry. MIT License.
   ============================================================================ */

const CHG_NAME_MAX = 30;


/** A name shortened for a sentence. */
function chgName(s) {
  const t = String(s || '').replace(/\s+/g, ' ').trim() || 'Untitled page';
  return `“${t.length > CHG_NAME_MAX ? `${t.slice(0, CHG_NAME_MAX - 1)}…` : t}”`;
}


/**
 * What changed between two copies of the story (JSON text, or the stories themselves), in words: { text, pid } where `pid` is the page
 * most worth showing (the one that changed, was added or comes back), or '' when no single page is involved. It names the first kind
 * of change it finds, not every change. Never throws: an unreadable copy gives a generic sentence.
 */
function describeChange(beforeText, afterText) {
  let a;
  let b;
  try {
    a = typeof beforeText === 'string' ? JSON.parse(beforeText) : beforeText;
    b = typeof afterText === 'string' ? JSON.parse(afterText) : afterText;
  } catch {
    return { text: 'Edit the story', pid: '' };
  }
  if (!a || !b || typeof a !== 'object' || typeof b !== 'object') return { text: 'Edit the story', pid: '' };
  const pa = Array.isArray(a.passages) ? a.passages : [];
  const pb = Array.isArray(b.passages) ? b.passages : [];
  if (a.id !== b.id) return { text: 'Open another story', pid: '' };
  const idsA = new Set(pa.map(p => p.id));
  const idsB = new Set(pb.map(p => p.id));
  const added = pb.filter(p => !idsA.has(p.id));
  const gone = pa.filter(p => !idsB.has(p.id));
  if (added.length === 1 && !gone.length) return { text: `Add page ${chgName(added[0].name)}`, pid: added[0].id };
  if (gone.length === 1 && !added.length) return { text: `Delete page ${chgName(gone[0].name)}`, pid: gone[0].id };
  if (added.length || gone.length) {
    const n = added.length + gone.length;
    return { text: added.length && gone.length ? `Change ${n} pages (some added, some deleted)` : added.length ? `Add ${added.length} pages` : `Delete ${gone.length} pages`, pid: (added[0] || gone[0]).id };
  }
  const byA = Object.create(null);
  pa.forEach(p => (byA[p.id] = p));
  const changed = pb.filter(p => JSON.stringify(p) !== JSON.stringify(byA[p.id]));
  if (!changed.length) {
    if (pa.map(p => p.id).join() !== pb.map(p => p.id).join()) {
      const moved = pb.find((p, i) => pa[i] && pa[i].id !== p.id);
      return { text: moved ? `Move page ${chgName(moved.name)}` : 'Reorder the pages', pid: moved ? moved.id : '' };
    }
    if (JSON.stringify(a.items) !== JSON.stringify(b.items)) return describeItems(a.items || [], b.items || []);
    if (JSON.stringify(a.givens) !== JSON.stringify(b.givens)) return { text: 'Change a Given question', pid: '' };
    if (a.start !== b.start) return { text: 'Change the start page', pid: b.start };
    if (a.title !== b.title) return { text: 'Change the story title', pid: '' };
    if (a.author !== b.author) return { text: 'Change the author', pid: '' };
    if (JSON.stringify(a.game) !== JSON.stringify(b.game)) return { text: 'Change the game options', pid: '' };
    if (JSON.stringify(a.langs) !== JSON.stringify(b.langs) || a.lang0 !== b.lang0 || a.lang0c !== b.lang0c) return { text: 'Change the translations', pid: '' };
    return { text: 'Edit the story', pid: '' };
  }
  if (changed.length > 1) return { text: `Change ${changed.length} pages`, pid: changed[0].id };
  const q = changed[0];
  const o = byA[q.id];
  const nm = chgName(q.name);
  const text =
    o.name !== q.name ? `Rename page ${chgName(o.name)} to ${nm}`
    : (o.choices || []).length < (q.choices || []).length ? `Add a choice on ${nm}`
    : (o.choices || []).length > (q.choices || []).length ? `Delete a choice on ${nm}`
    : (o.blocks || []).length < (q.blocks || []).length ? `Add a paragraph on ${nm}`
    : (o.blocks || []).length > (q.blocks || []).length ? `Delete a paragraph on ${nm}`
    : o.ending !== q.ending || o.valence !== q.valence ? `Change the ending setting of ${nm}`
    : o.color !== q.color || o.note !== q.note ? `Mark page ${nm}`
    : JSON.stringify([o.gives, o.takes, o.adds, o.sends]) !== JSON.stringify([q.gives, q.takes, q.adds, q.sends]) ? `Change what page ${nm} gives or takes`
    : JSON.stringify(o.choices) !== JSON.stringify(q.choices) ? `Edit a choice on ${nm}`
    : `Edit page ${nm}`;
  return { text, pid: q.id };
}


/** The items part of describeChange. */
function describeItems(ia, ib) {
  const idsA = new Set(ia.map(x => x.id));
  const idsB = new Set(ib.map(x => x.id));
  const added = ib.filter(x => !idsA.has(x.id));
  const gone = ia.filter(x => !idsB.has(x.id));
  if (added.length === 1 && !gone.length) return { text: `Add item ${chgName(added[0].name)}`, pid: '' };
  if (gone.length === 1 && !added.length) return { text: `Delete item ${chgName(gone[0].name)}`, pid: '' };
  if (added.length || gone.length) return { text: `Change ${added.length + gone.length} items`, pid: '' };
  const was = Object.create(null);
  ia.forEach(x => (was[x.id] = x));
  const ch = ib.filter(x => JSON.stringify(x) !== JSON.stringify(was[x.id]));
  if (ch.length === 1) return { text: was[ch[0].id].name !== ch[0].name ? `Rename item ${chgName(was[ch[0].id].name)} to ${chgName(ch[0].name)}` : `Edit item ${chgName(ch[0].name)}`, pid: '' };
  return { text: ch.length ? `Change ${ch.length} items` : 'Reorder the items', pid: '' };
}


export { describeChange };
